import{z as s,x as B,o as E,c as i,q as t,j as r,D as a,d as n,s as l,S as d}from"./chunks/framework.C8m1ZpeB.js";const k=JSON.parse('{"title":"流式重排与增量解析","description":"","frontmatter":{"title":"流式重排与增量解析","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dec-stream-reparse.md","filePath":"llm/dec-stream-reparse.md","lastUpdated":1791413859000}'),A={name:"llm/dec-stream-reparse.md"};function p(c,e,m,_,h,C){const o=B("Mermaid");return E(),i("div",null,[e[2]||(e[2]=t('<h1 id="流式重排与增量解析" tabindex="-1">流式重排与增量解析 <a class="header-anchor" href="#流式重排与增量解析" aria-label="Permalink to &quot;流式重排与增量解析&quot;">​</a></h1><div class="epigraph"><p>客户端要的不是 token，是事件：字段开始了、值稳了、对象闭合了；把 token 流直接推给前端，等于把解析器的活推给浏览器。</p><footer>—— 据 HuggingFace / tiktoken 增量解码与部分 JSON 解析器实践整理</footer></div><p><a href="/llm/dec-dialogue-state-stop">上一课</a>把「何时停」钉在会话状态上；停之前的每一段怎么交付，是本课的地盘。底层缝已经钉过：<a href="/llm/streaming-detokenize">流式 detokenize</a> 写了字节缓冲与稳定前缀，<a href="/llm/stop-sequences">stop 课</a>写了停用串命中后的挂起。本课往上走一层：把 token 流变成<strong>事件流</strong>——结构化输出的增量解析、乱序块的重排、以及帧协议。前端要边收边渲染，几 KB 的 JSON 不能等闭合。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>三种交付形态的缺口。其一，纯文本流：token 到哪发到哪，detokenize 课已经解决稳定前缀；但结构化输出不能这样发——半截 JSON 对客户端不可解析（<a href="/llm/json-schema-decode">JSON Schema 课</a>的边界），用户看着一串花括号没有意义。其二，等闭合再发：最稳，TTFT 退化到整段生成完，长结构上不可接受。其三，增量解析：边生成边报告结构事件，<code>key_start</code>、<code>value_chunk</code>、<code>object_end</code>，前端按事件渲染骨架与填充值。缺口在：事件从哪来、半截字符串 token 怎么算、多个生成块乱序到达时谁保证顺序。</p><p><span class="marginnote">数字实例：一个 50 字段的嵌套 JSON 约 3000 token，按 30 token/秒生成要 100 秒。等闭合再发，用户盯着空白等 100 秒；增量解析下，第 1 秒就能看到表单骨架和第一个字段名——总时间没变，「感觉完成」的时间提前了两个数量级。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>事件层与文法共享状态。</strong> 文法掩码的自动机本来就知道「当前在哪个字段、值是字符串还是数字」（<a href="/llm/grammar-decode">文法课</a>），增量解析器不必从字节盲猜：向自动机要当前格局，格局每跳一次就发出对应事件。约束解码保证了「目前已是活前缀」，解析器只需报告进展，不需纠错——这是约束与流式互相成全的地方。</p><p><strong>只发稳定子树。</strong> 未闭合的字符串值只发已稳定部分（detokenize 课的稳定前缀规则对每个字段值单独成立）；枚举值在整体闭合前只标「候选」。replace_tail 帧允许修正未稳定尾巴。</p><p><strong>重排缓冲。</strong> 并行块（多候选、多分片、工具结果与正文）各自编号，交付层按序提交：序号小的未到，已到的先进缓冲。重排的代价是缓冲内存与首事件延迟，收益是前端逻辑不需要处理乱序。</p><p><span class="marginnote">为什么重要：网络不会保证先发的先到——乱序是常态不是故障。前端如果直接「来一帧画一帧」，用户就会看到 JSON 的值出现在键名前面、工具结果插在句子中间这类诡异画面。服务端先按序号排好队再交付，等于把一个全平台都要写的难题收进一处解决。</span></p>',11)),(E(),r(d,null,{default:a(()=>[l(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TOK%5B%22token%20%E6%B5%81%22%5D%20--%3E%20DT%5B%22%E5%A2%9E%E9%87%8F%20detokenize%EF%BC%9A%E7%A8%B3%E5%AE%9A%E5%89%8D%E7%BC%80%22%5D%0A%20%20DT%20--%3E%20FSM%7B%22%E6%96%87%E6%B3%95%E6%A0%BC%E5%B1%80%E5%8F%98%E5%8C%96%3F%22%7D%0A%20%20FSM%20--%3E%7C%E6%98%AF%7C%20EV%5B%22%E5%8F%91%E7%BB%93%E6%9E%84%E4%BA%8B%E4%BB%B6%EF%BC%9Akey_start%20%2F%20value%20%2F%20close%22%5D%0A%20%20FSM%20--%3E%7C%E5%90%A6%7C%20VC%5B%22value_chunk%20%E5%A2%9E%E9%87%8F%22%5D%0A%20%20EV%20--%3E%20RO%5B%22%E6%8C%89%E5%BA%8F%E5%8F%B7%E9%87%8D%E6%8E%92%E7%BC%93%E5%86%B2%22%5D%0A%20%20VC%20--%3E%20RO%0A%20%20RO%20--%3E%20FRAME%5B%22%E5%B8%A7%E5%8D%8F%E8%AE%AE%EF%BC%9Aappend%20%2F%20replace_tail%20%2F%20event%22%5D%0A%20%20FRAME%20--%3E%20UI%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=t('<h3 id="帧协议是兼容性契约" tabindex="-1">帧协议是兼容性契约 <a class="header-anchor" href="#帧协议是兼容性契约" aria-label="Permalink to &quot;帧协议是兼容性契约&quot;">​</a></h3><p>帧至少三种：<code>append</code>（追加稳定文本）、<code>replace_tail</code>（修正未稳定后缀）、<code>event</code>（结构事件）。协议变更即接口变更：换引擎不能换帧语义，网关要能降级（不支持 event 的客户端退化为 append 加闭合后整段校验）。这与 detokenize 课的两种帧一脉相承，event 是结构层加出来的第三种。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>增量解析的正确性来自两层保证的叠加：detokenize 层保证不把半个 UTF-8 码点或未定空格标记当字符发出；自动机层保证到过的每个格局都是 schema 的活前缀。解析器报错因此是强信号：约束解码下「解析卡住」几乎总是帧协议或分词器问题，不是模型写错了结构——掩码已经禁止了非法结构，这是<a href="/llm/json-constrained-decode">结构化输出</a>的契约。投机一次提交多个 token 时，事件层按批过增量状态机，与 detokenize 课的批处理结论同构。</p><p>重排的语义按交付物定义：文本流重排在字节上（乱序块不能拼错），事件流重排在事件序上（<code>key_start</code> 先于其 <code>value_chunk</code>）。两类序号不要混用；混用的典型事故是工具结果块插进正文事件序，前端把结果文本渲染进答案。</p><p><span class="marginnote">事件层引入一个新延迟项：首事件等待到第一个稳定事件（通常第一个键名闭合）才可发。验收结构化流式要报「首事件延迟」与「首字节延迟」两个数，只报后者会高估体验。</span></p><p>第一张图画事件从哪来；一个未闭合字符串值的尾巴如何边长边修正，是 replace_tail 帧要回答的另一件事：</p>',7)),(E(),r(d,null,{default:a(()=>[l(o,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20T1%5B%22token%EF%BC%9A'%E5%8C%97'%22%5D%20--%3E%20ST%5B%22%E7%A8%B3%E5%AE%9A%E9%83%A8%E5%88%86%EF%BC%9A%E5%8C%97%3Cbr%2F%3E%E5%8F%91%20append%20%E5%B8%A7%22%5D%0A%20%20T2%5B%22token%EF%BC%9A'%E4%BA%AC%E6%97%B6%E9%97%B4'%22%5D%20--%3E%20ST2%5B%22%E7%A8%B3%E5%AE%9A%EF%BC%9A%E5%8C%97%E4%BA%AC%3Cbr%2F%3E%E5%8F%91%20replace_tail%20%E4%BF%AE%E6%AD%A3%E5%B0%BE%E5%B7%B4%22%5D%0A%20%20T3%5B%22token%EF%BC%9A'%E6%98%AF%E6%99%B4'%22%5D%20--%3E%20ST3%5B%22%E7%A8%B3%E5%AE%9A%EF%BC%9A%E5%8C%97%E4%BA%AC%3Cbr%2F%3E%E5%B0%BE%E5%B7%B4%E4%BB%8D%E6%98%AF%E5%80%99%E9%80%89%22%5D%0A%20%20T4%5B%22token%EF%BC%9A%E9%97%AD%E5%90%88%E5%BC%95%E5%8F%B7%22%5D%20--%3E%20FIN%5B%22%E5%80%BC%E6%95%B4%E4%BD%93%E9%97%AD%E5%90%88%3Cbr%2F%3E%E5%8F%91%20value_end%20%E4%BA%8B%E4%BB%B6%EF%BC%9A%E6%9C%80%E7%BB%88%E6%96%87%E6%9C%AC%E5%AE%9A%E6%A0%BC%22%5D%0A%20%20ST%20-.-%3E%7C%22%E5%90%8E%E7%BB%AD%E6%AF%8F%E5%B8%A7%E8%A6%86%E7%9B%96%E4%B8%8A%E4%B8%80%E5%B8%A7%E7%9A%84%E5%B0%BE%E5%B7%B4%22%7C%20ST2%0A%20%20ST2%20-.-%3E%20ST3%0A%20%20ST3%20-.-%3E%20FIN%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[n(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=t('<p><span class="marginnote">术语翻译：replace_tail 的意思是「我上一帧末尾那段还没定，现在用这个新版本替换它」。像填表时铅笔写的草稿——可以擦了重写，但一旦单元格关闭（字符串的闭合引号到了），就换成钢笔定稿。客户端只要永远重画「当前尾巴」，就不需要懂分词器的半字符问题。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>事件流不降低存储门槛：半截 JSON 仍然不能进数据库，入库在闭合与校验之后（<a href="/llm/json-schema-decode">JSON Schema 课</a>的位置不变，本课只是把「等闭合」从客户端挪到服务端事件层）。事件粒度是带宽与延迟的权衡：逐字符事件打爆网关，整段事件退化成非流式；按字段与值切块是默认工作点。无约束流量没有格局可用，事件层退化为纯 detokenize——不要为普通文本强造伪事件。下一课管解码完成后的最后一公里：后处理管线。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>交付分三层：纯文本流（稳定前缀）、事件流（结构增量）、整段（闭合后）；结构化输出选事件流。</li><li>事件与文法格局共享状态：掩码保证活前缀，解析器只报告不纠错。</li><li>帧协议三种：append、replace_tail、event；协议变更即接口变更，网关可降级。</li><li>重排按序号提交，文本序与事件序分开编号；乱序缓冲换首事件延迟。</li><li>「解析卡住」在约束下是强信号：先查帧协议与分词器，再怀疑模型。</li><li>出处：据 HuggingFace <code>TextIteratorStreamer</code>、tiktoken 增量解码与部分 JSON 解析器实践整理；底层缝见流式 detokenize 与 stop sequences 课。</li></ul>',5))])}const T=s(A,[["render",p]]);export{k as __pageData,T as default};
